#!/usr/bin/env python3
"""Complete changed boundary models for the two twelve-slot frontier weights."""
from pathlib import Path
from itertools import product
import sympy as s
import json,hashlib
HERE=Path(__file__).resolve().parent;OUT=HERE/'weighted-124-125';OUT.mkdir(exist_ok=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def enc(p,V):return [{'exponent':list(e),'coefficient':str(c)} for e,c in s.Poly(s.expand(p),*V).terms() if c]
def main():
 a,b,c,u,w,v=s.symbols('a b c u w v');mu,P,nu,A2,A3,L,B,E2,E3,E4,H1,H2,T=s.symbols('mu P nu A2 A3 L B E2 E3 E4 H1 H2 T');models=[]
 bracket=lambda f,g:s.diff(f,u)*s.diff(g,w)-s.diff(f,w)*s.diff(g,u)
 def jac(f,g,h,r):return s.expand(f*bracket(g,h)+2*g*bracket(f,h)+r*h*bracket(g,f))
 for r in [4,5]:
  names=[mu,P,nu,A2,A3,L,B]+([E2,E3] if r==4 else [E3,E4])+[H1,H2,T];f=1+mu*u+P*u*u+nu*w;g=u+A2*u*u+A3*u**3+L*w+B*u*w;h=w+(E2*u*u+E3*u**3 if r==4 else E3*u**3+E4*u**4)+H1*u*w+H2*u*u*w+T*w*w;sub={u:a*a*b,w:a**r*c};F=[s.expand(a*f.subs(sub)),s.expand(a**-2*g.subs(sub)),s.expand(a**-r*h.subs(sub))];basis=[(i,e) for i in range(3) for e in product(range(8),repeat=3) if 2<=sum(e)<=7 and e[0]-2*e[1]-r*e[2]==[1,-2,-r][i]];assert len(basis)==12
  actual={(i,e[:3]) for i,z in enumerate(F) for e,co in s.Poly(z,a,b,c,*names).terms() if sum(e[:3])>=2};assert actual==set(basis);J=jac(f,g,h,r);assert s.expand(s.det(s.Matrix(F).jacobian([a,b,c]))-J.subs(sub))==0;parent=HERE/'weight-resonance7/mixed-cases'/('p1q2r'+str(r)+'.json');d={'status':'complete-primary-changed-model','source_sha256':sha(Path(__file__)),'r':r,'weights':[1,-2,-r],'parameter_names':list(map(str,names)),'basis':[{'output':i,'exponent':list(e)} for i,e in basis],'source_outputs':[enc(z,[a,b,c]+names) for z in F],'quotient_outputs':[enc(z,[u,w]+names) for z in [f,g,h]],'quotient_jacobian':enc(J,[u,w]+names),'native_generators':[enc(z,names) for z in s.Poly(J-1,u,w).coeffs()],'parent_timeout_model_sha256':sha(parent)};ip=OUT/('r'+str(r)+'.json');ip.write_text(json.dumps(d,indent=2)+'\n');models.append({'r':r,'input':ip.name,'input_sha256':sha(ip),'nonlinear_slots':12,'native_generators':len(d['native_generators'])});print('MODEL',r,12,len(d['native_generators']),flush=True)
 r,mu,P,A0,A1,B2,B3,C,D1,D2,E2,E3,E4,rho=s.symbols('r mu P A0 A1 B2 B3 C D1 D2 E2 E3 E4 rho');params=[r,mu,P,A0,A1,B2,B3,C,D1,D2,E2,E3,E4,rho];phi=1+mu*u+P*u*u;A=A0+A1*u;B=u+B2*u*u+B3*u**3;D=1+D1*u+D2*u*u;E=E2*u*u+E3*u**3+E4*u**4;g=A*w+B;h=C*w*w+D*w+E;J=jac(phi,g,h,r);cofs=[s.diff(phi,u)*(2*B*D-r*A*E)+phi*(s.diff(B,u)*D-A*s.diff(E,u)),s.diff(phi,u)*((2-r)*A*D+4*B*C)+phi*(s.diff(A,u)*D+2*s.diff(B,u)*C-A*s.diff(D,u)),(4-r)*s.diff(phi,u)*A*C+2*phi*s.diff(A,u)*C];assert all(s.expand(s.Poly(J,w).nth(i)-z)==0 for i,z in enumerate(cofs));shear=s.expand(jac(phi,g,h-rho*g*g,r)-J);assert s.expand(shear-(r-4)*rho*g*g*bracket(phi,g))==0
 univ={'parameters':list(map(str,params)),'forms':[enc(z,[u,w]+params) for z in [phi,A,B,D,E,g,h]],'jacobian':enc(J,[u,w]+params),'w_coefficients':[enc(z,[u]+params) for z in cofs],'target_shear_difference':enc(shear,[u,w]+params)}
 r,A,B,alpha,beta,T=s.symbols('r A B alpha beta T');hs=s.symbols('h0:3');ks=s.symbols('k0:3');params=[r,A,B,alpha,beta,T]+list(hs)+list(ks);G0=A*u+B;G1=alpha*u+beta;H0=sum(hs[i]*u**i for i in range(3));HH1=sum(ks[i]*u**i for i in range(3));G=G0+v*G1;H=H0+v*HH1+T*v*v;J=s.expand((2*G+v*s.diff(G,v))*s.diff(H,u)-s.diff(G,u)*(r*H+v*s.diff(H,v)));cofs=[2*G0*s.diff(H0,u)-r*A*H0,3*G1*s.diff(H0,u)+2*G0*s.diff(HH1,u)-r*alpha*H0-(r+1)*A*HH1,3*G1*s.diff(HH1,u)-(r+1)*alpha*HH1-(r+2)*A*T,-(r+2)*alpha*T];assert all(s.expand(s.Poly(J,v).nth(i)-z)==0 for i,z in enumerate(cofs));graph={'parameters':list(map(str,params)),'forms':[enc(z,[u,v]+params) for z in [G0,G1,H0,HH1,G,H]],'jacobian':enc(J,[u,v]+params),'v_coefficients':[enc(z,[u]+params) for z in cofs],'complete_boundary_degree_bounds':{'r4':[1,2],'r5':[1,1]}}
 aa=s.Symbol('A');ee=-(1+5*aa)/2;al=-s.Rational(3,2)*(1+aa);mm=(5+aa)/2;GG0=aa*u-1;GG1=1+al*u;HH0=1+ee*u;HH1=-GG1**2;E0=s.expand(2*GG0*s.diff(HH0,u)-5*aa*HH0-1);E1=s.expand(3*GG1*s.diff(HH0,u)+2*GG0*s.diff(HH1,u)-5*al*HH0-6*aa*HH1);Q=s.Poly(E0,u).nth(1);S=s.Poly(E1,u).nth(1);X,Y,gcd=s.gcdex(Q,S,aa);assert gcd==1 and s.expand(X*Q+Y*S)==1;r5={'parameters':['A'],'e':enc(ee,[aa]),'alpha':enc(al,[aa]),'mu':enc(mm,[aa]),'forms':[enc(z,[u,aa]) for z in [GG0,GG1,HH0,HH1]],'E0':enc(E0,[u,aa]),'E1':enc(E1,[u,aa]),'residuals':[enc(z,[aa]) for z in [Q,S]],'multipliers':[enc(z,[aa]) for z in [X,Y]],'multiplier_terms':len(enc(X,[aa]))+len(enc(Y,[aa]))}
 out={'status':'complete-primary-structural-identities','source_sha256':sha(Path(__file__)),'univariate':univ,'graph':graph,'r5_residual':r5};sp=OUT/'structural-identities.json';sp.write_text(json.dumps(out,indent=2)+'\n');cp={'status':'complete','source_sha256':sha(Path(__file__)),'models':models,'structural_identities_sha256':sha(sp),'new_method':'integer-boundary leading-power subtraction, graph transverse resonance and four-term one-variable unit; no old native ideal replay or cap increase','old_four_native_timeouts_unchanged':True};(OUT/'checkpoint.json').write_text(json.dumps(cp,indent=2)+'\n');print('STRUCTURE COMPLETE r5 unit terms',r5['multiplier_terms'])
if __name__=='__main__':main()
